// Run only against a directory generated by prepare-visual.cjs.
const fs=require('fs'),path=require('path'),cp=require('child_process'),crypto=require('crypto'),assert=require('assert');
const root=path.resolve(process.argv[2]||'');
const manifest=JSON.parse(fs.readFileSync(path.join(root,'manifest.json')));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const evidence={root,version:manifest.version,consistency:{},launches:[],comparisons:[]};
for(const [file,hash] of Object.entries(manifest.files))assert.equal(sha(fs.readFileSync(path.join(root,file.replace('/package.json','/theme/package.json').replace('/themes/','/theme/themes/')))),hash,file);
assert.equal(fs.readFileSync(path.join(root,'baseline/data/User/settings.json'),'utf8'),fs.readFileSync(path.join(root,'current/data/User/settings.json'),'utf8'),'Initial profile settings differ');
const hashesPath=path.join(root,'extensions-sha256.json');
const hashes=fs.existsSync(hashesPath)?JSON.parse(fs.readFileSync(hashesPath)):{};
for(const [file,hash] of Object.entries(hashes))if(!file.startsWith('local-audit.theme-visual-probe-0.0.1'))assert.equal(sha(fs.readFileSync(path.join(root,'extensions',file))),hash,file);
evidence.consistency={themesMatchManifest:true,initialSettingsEqual:true,extensionFilesVerified:Object.keys(hashes).length,fullExtensionHashCheck:Object.keys(hashes).length?'passed':'pending'};
// Refresh our probe after validating the original frozen extension snapshot.
const probe=path.join(root,'extensions/local-audit.theme-visual-probe-0.0.1');fs.cpSync(path.join(__dirname,'visual-probe'),probe,{recursive:true});
evidence.probeSha256=Object.fromEntries(['extension.cjs','tests.cjs','package.json'].map(f=>[f,sha(fs.readFileSync(path.join(probe,f)))]));
const exe=path.resolve(manifest.app,'../../../Code.exe');
async function run(side){
 const output=path.join(root,side,'runtime-captures.json');assert(!fs.existsSync(output),'Existing captures: prepare a fresh session instead of overwriting evidence.');const stdout=fs.openSync(path.join(root,side,'runtime-launch.log'),'w');
 const env={...process.env,THEME_AUDIT_OUTPUT:output};delete env.ELECTRON_RUN_AS_NODE;
 const args=['--new-window','--sync','off','--locale','en-US','--skip-welcome','--skip-release-notes','--disable-workspace-trust','--user-data-dir',path.join(root,side,'data'),'--extensions-dir',path.join(root,'extensions'),'--extensionDevelopmentPath='+path.join(root,side,'theme'),'--extensionTestsPath='+path.join(probe,'tests.cjs'),path.join(root,'fixtures')];
 const child=cp.spawn(exe,args,{env,cwd:root,windowsHide:true,stdio:['ignore',stdout,stdout]});
 return await new Promise(resolve=>{child.on('error',error=>resolve({side,error:String(error),output}));child.on('exit',(code,signal)=>resolve({side,code,signal,output,capturesPresent:fs.existsSync(output)}));});
}
(async()=>{
 for(const side of ['baseline','current']){const result=await run(side);evidence.launches.push(result);fs.writeFileSync(path.join(root,'execution.json'),JSON.stringify(evidence,null,2));console.log(result);}
 const outputs=['baseline','current'].map(s=>path.join(root,s,'runtime-captures.json'));
 if(outputs.every(p=>fs.existsSync(p))){const [a,b]=outputs.map(p=>JSON.parse(fs.readFileSync(p)).results);for(const left of a){const right=b.find(r=>r.label===left.label&&r.file===left.file);const fields=['documentSha256','theme','language','semanticSetting','semanticSettingSources','tokenCustomizations','semanticCustomizations','font','extensions','semantic'];const differing=fields.filter(k=>JSON.stringify(left[k])!==JSON.stringify(right?.[k]));evidence.comparisons.push({label:left.label,file:left.file,differing,stable:left.stable&&right?.stable,providerPresent:left.semantic?.status==='returned'&&right?.semantic?.status==='returned',rendering:'pending'});}}
 fs.writeFileSync(path.join(root,'execution.json'),JSON.stringify(evidence,null,2));
})().catch(e=>{evidence.error=String(e);fs.writeFileSync(path.join(root,'execution.json'),JSON.stringify(evidence,null,2));console.error(e);process.exitCode=1;});
